ng the termination checklist for {field.employee} at {field.site_name}, terminated {field.termination_date}.\n\nPlease deactivate this splashcarwashes.com email address: {field.email_to_deactivate}\n\nPlease reply to {field.completed_by_email} once it's done.\n\nThis is a confidential personnel matter. Please don't forward it.","transitions":[{"to":"request_divvy_deactivation","label":"Sent"}]},{"id":"request_divvy_deactivation","label":"Request Divvy deactivation","kind":"email","send_if":{"field_key":"steps","equals":["divvy_deactivation"]},"recipients":[{"type":"static_emails","emails":["bvalentine@splashcarwashes.com"]}],"subject_template":"Please deactivate Divvy: {field.employee}","body_template":"{field.completed_by_name} ({field.completed_by_email}) is completing the termination checklist for {field.employee} at {field.site_name}, terminated {field.termination_date}.\n\nPlease deactivate their Divvy access and card.\n\nPlease reply to {field.completed_by_email} once it's done.\n\nThis is a confidential personnel matter. Please don't forward it.","transitions":[{"to":"request_isolved","label":"Sent"}]},{"id":"request_isolved","label":"Request iSolved manager access removed","kind":"email","send_if":{"field_key":"steps","equals":["isolved"]},"recipients":[{"type":"static_emails","emails":["payroll@splashcarwashes.com","slowe@splashcarwashes.com"]}],"subject_template":"Please remove iSolved manager access: {field.employee}","body_template":"{field.completed_by_name} ({field.completed_by_email}) is completing the termination checklist for {field.employee} at {field.site_name}, terminated {field.termination_date}.\n\nPlease remove their iSolved manager access.\n\nPlease reply to {field.completed_by_email} once it's done.\n\nThis is a confidential personnel matter. Please don't forward it.","transitions":[{"to":"request_spot_ai","label":"Sent"}]},{"id":"request_spot_ai","label":"Request Spot AI access removed","kind":"email","send_if":{"field_key":"steps","equals":["spot_ai"]},"recipients":[{"type":"static_emails","emails":["rwilliams@splashcarwashes.com"]}],"subject_template":"Please remove Spot AI access: {field.employee}","body_template":"{field.completed_by_name} ({field.completed_by_email}) is completing the termination checklist for {field.employee} at {field.site_name}, terminated {field.termination_date}.\n\nPlease remove Spot AI access for this email address: {field.spot_ai_email}\n\nPlease reply to {field.completed_by_email} once it's done.\n\nThis is a confidential personnel matter. Please don't forward it.","transitions":[{"to":"filed","label":"Sent"}]},{"id":"filed","label":"Filed","kind":"outcome","tint":"neutral","transitions":[]}]}}$tc$::jsonb
  from public.forms f
 where f.slug = 'employee-termination-checklist' and v.id = f.draft_version_id;

select f.slug, f.audience, f.status, f.scope_location_field_key, f.email_drafts, f.test_email_to,
       '/forms/' || f.link_key as secret_url,
       jsonb_array_length(v.schema->'fields') as fields
  from public.forms f join public.form_versions v on v.id = f.draft_version_id
 where f.slug in ('employee-termination-report', 'employee-termination-checklist');
